//! A farm's food: `RGE_Action_Make` (action type 21, vtable `RGE_Action_Make::vftable`), the
//! default task of the farms (50, 1187), the fish trap (199) and the pastures (1893, 1897). The
//! RGE factory makes it (`FUN_140a97e00`, case 0x15, constructor `FUN_140a99430`); the TRIBE
//! factory (`FUN_140aca4b0`) has no case of its own for it.
//!
//! The farm holds what it made (`+0x308`, `+0x310`) up to its master's capacity
//! (`attribute_max_amount`, `+0x61c`): the Make adds its master's work rate (plus the farm's
//! powerup) times the task's `work_val1` per second, and the farmers take from it. The food
//! still to make starts at the player's farm food (attribute 36) or fish trap food (88); once it
//! is made and the farmers took the last of it, the farm's slot 0xd8 sets its hit points to 0.

/// The task's resource for which `set_state(6)` reads the farm food (`FUN_140a99d60`'s
/// `task+0x20 == 0x10`): the farms' and the pastures' food kind.
pub const FARM_FOOD_KIND: i16 = 16;

/// The player's attribute `set_state(6)` reads for a task of [`FARM_FOOD_KIND`]
/// (`player+0x100` at `+0x120`): Farm Food Amount.
pub const FARM_FOOD: usize = 36;

/// The player's attribute `set_state(6)` reads for any other task (`player+0x100` at `+0x2c0`):
/// Fish Trap Food Amount.
pub const FISH_TRAP_FOOD: usize = 88;

/// `RGE_Action_Make`: its state (`+0x18`), the food still to make (`+0x44`, the base's
/// `mTimer`), the food it makes in all (`+0x68`, the save's `work_timer`) and its task (`+0x48`).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MakeAction {
    /// `+0x18`.
    pub state: u8,
    /// `+0x44`: the food still to make.
    pub remaining: f32,
    /// `+0x68`: the food made in all; the constructor's 120.0 never shows, as
    /// [`MakeAction::start`] sets it at once.
    pub total: f32,
    /// `+0x48`: the master's default task.
    pub task: Task,

impl MakeAction {
    /// The default task's start (slot 0x7f0, `FUN_14106eb40`): the factory's action
    /// (`FUN_140a99430`), then `set_only_action` (slot 0x808, `FUN_14106e990`), whose push
    /// (`FUN_140a977e0`) runs `first_in_stack` (`FUN_140a99980`): `set_state(6)`, then a task
    /// resource other than the farm's own holding replaces it, with nothing held
    /// (`FUN_14119d310` with 0).
    #[must_use]
    pub fn start(task: Task, attributes: &[f32], held: &mut Held<'_>) -> Self {
        // the factory's constructor (FUN_140a99430) sets +0x68 to 120.0, which set_state(6)
        // replaces at once
        let mut make = Self {
            state: 0,
            remaining: 0.0,
            total: 120.0,
            task,
        };
        make.set_state(MAKING, attributes);
        if 0 <= task.attribute_type && *held.attribute_type != task.attribute_type {
            *held.attribute_type = task.attribute_type;
            *held.amount = 0.0;
        }
        make
    }

    /// `set_state` (`FUN_140a99d60`): state 6 takes the player's food to make (attribute 36 for
    /// a task of the farm food kind, else 88) as both what is left and what is made in all.
    pub fn set_state(&mut self, state: u8, attributes: &[f32]) {
        self.state = state;
        if state == MAKING {
            let kind = if self.task.attribute_type == FARM_FOOD_KIND {
                FARM_FOOD
            } else {
                FISH_TRAP_FOOD
            };
            self.remaining = attributes.get(kind).copied().unwrap_or(0.0);
            self.total = self.remaining;
        }
    }

    /// The update (`FUN_140a99e30`). State 1 is done. In state 6, while food is left to make (or
    /// none was ever to be made), the farm's holding grows by its work rate times the task's
    /// `work_val1` and the update's seconds, within its capacity (`FUN_14119d320` with 1 and 1),
    /// and what it gained is no longer left to make; a task with a work flag (`+0x34`) adds to
    /// its player instead, so nothing is taken off. Once all is made, a farm that holds nothing
    /// (not a pasture) runs its slot 0xd8. The game's `+0xc14` (`FUN_140c884c0`), which makes
    /// 1000 at once, is 0, as the tick oracle holds it. The other states do nothing.
    pub fn update(&mut self, held: &mut Held<'_>, farm: Farm) -> MakeStep {
        let mut step = MakeStep::default();
        match self.state {
            DONE => step.done = true,
            MAKING if 0.0 < self.remaining || self.total <= 0.0 => {
                let rate = farm.work_rate * self.task.work_val1 * farm.dt;
                let before = *held.amount;
                if self.task.work_flag == 0 {
                    // FUN_14119d320: add, then at most the capacity
                    *held.amount += rate;
                    let capacity = f32::from(farm.capacity);
                    if capacity < *held.amount {
                        *held.amount = capacity;
                    }
                } else {
                    step.to_player = Some((self.task.attribute_type, rate));
                }
                self.remaining -= *held.amount - before;
            }
            // slot 0xd8: a combat object's or building's (FUN_141211340) spares class 42, then
            // FUN_14118f580
            MAKING if !UNEXHAUSTED.contains(&farm.master_id) && *held.amount <= 0.0 => {
                step.exhausted =
                    farm.kind < TRIBE_COMBAT_TYPE || farm.class != NEVER_EXHAUSTED_CLASS;
            }
            _ => {}
        }

impl Unit {
    /// A farm's Make in its update: the food it makes, the player's share, the farm that runs
    /// out, and the end. A Make that this update started (`makes_from_now`) waits for the next
    /// update.
    pub(crate) fn make_part(
        &mut self,
        c: &mut Context<'_>,
        makes_from_now: bool,
    ) -> Result<(), GenieError> {
        if let Some(make) = self.make.as_mut().filter(|_| !makes_from_now) {
            let master = c.masters.and_then(|m| m.get(self.life.master_id)).ok_or(
                GenieError::unsupported("a Make of a master the slice does not have"),
            )?;
            let farm = Farm {
                master_id: master.id,
                kind: master.kind,
                class: master.class,
                work_rate: master.work_rate + self.work_rate_powerup,
                capacity: master.capacity,
                dt: c.dt_seconds,
            };
            let step = make.update(
                &mut Held {
                    attribute_type: &mut self.life.attribute_type,
                    amount: &mut self.life.amount,
                },
                farm,
            );

/// The farm's default task in build 158041's `.dat` (master 50, task 0).
fn farm_task() -> Task {
    Task {
        action_type: MAKE,
        attribute_type: FARM_FOOD_KIND,
        attribute_type2: 0,
        work_val1: 1.0,
        ..Task::default()
    }
}

fn farm(master_id: i16) -> Farm {
    Farm {
        master_id,
        kind: 80,
        class: 49,
        work_rate: 0.4,
        capacity: 15,
        dt: 0.104,
    }
}

fn attributes() -> Vec<f32> {
    let mut a = vec![0.0; 100];
    (a[FARM_FOOD], a[FISH_TRAP_FOOD]) = (175.0, 225.0);
    a
}

#[test]
fn the_start_takes_the_farm_food_and_holds_the_task_s_resource_from_nothing() {
    let (mut kind, mut amount) = (0, 15.0);
    let make = MakeAction::start(
        farm_task(),
        &attributes(),
        &mut Held {
            attribute_type: &mut kind,
            amount: &mut amount,
        },
    );
    assert_eq!(
        (make.state, make.remaining, make.total),
        (MAKING, 175.0, 175.0)
    );
    assert_eq!((kind, amount), (FARM_FOOD_KIND, 0.0));

#[test]
fn the_update_fills_the_farm_within_its_capacity_and_counts_what_it_made() {
    let (mut kind, mut amount) = (FARM_FOOD_KIND, 14.98);
    let mut make = MakeAction {
        state: MAKING,
        remaining: 100.0,
        total: 175.0,
        task: farm_task(),
    };
    let mut held = Held {
        attribute_type: &mut kind,
        amount: &mut amount,
    };
    let step = make.update(&mut held, farm(50));
    assert_eq!(step, MakeStep::default());
    let gained = 15.0f32 - 14.98;
    assert_eq!((*held.amount, make.remaining), (15.0, 100.0 - gained));
    // at the capacity nothing more is made
    let _ = make.update(&mut held, farm(50));
    assert_eq!(make.remaining, 100.0 - gained);
    // a farmer took 5: the rate's share comes back
    *held.amount = 10.0;
    let _ = make.update(&mut held, farm(50));
    let rate = 0.4f32 * 1.0 * 0.104;
    assert_eq!(*held.amount, 10.0 + rate);
    assert_eq!(make.remaining, 100.0 - gained - (10.0 + rate - 10.0));

/// State 7 (case 6) with one stop: the work, `(work rate) × work_val1 × dt`, at most what the
/// target holds, times the productivity. A load that would pass the capacity ends the
/// gathering ([`Next::Drop`]); else the target loses the work, its last bit (above 0, below
/// 0.1) going with a thousandth of its master's first storage amount, the unit gains, and a
/// remainder below 0.1 of the capacity rounds the load up. A farm's food under the player's
/// attribute 96 is sold at once ([`Gatherer::sold`]); else a full load, or an empty target
/// that cannot be gathered empty (the combat object's slot 0x2b8), ends it. The game's
/// `+0xc14` (`FUN_140c884c0`) is 0, as the tick oracle holds it.
pub(super) fn gather(&self, target: &mut Victim, g: &mut Gatherer<'_>, dt: f32) -> Next {
    let work = (g.work_rate * self.task.work_value) * dt;
    let take = if work <= target.amount {
        work
    } else {
        target.amount
    };
    let capacity = g.capacity;
    let mut gain = g.productivity * take;
    if capacity < gain + *g.held {
        return Next::Drop;
    }
    target.amount += -take;
    // the last bit and the storage's share summed first (`0x140a8f751`)
    if target.amount < REMAINDER && 0.0 < target.amount {
        gain += target.storage * LAST_BIT + target.amount;
        target.amount = 0.0;
    }
    *g.held += gain;
    let over = (*g.held - capacity).abs();
    if *g.held < capacity && over < REMAINDER && over <= target.amount {
        target.amount += -over;
        *g.held += over;
    }
    // a farm's food sold at once (attribute 96): the load goes to the player as food (slot
    // 0xf8 with 1, the caller's), the unit holds none, and the gathering goes on
    if 0.0 < g.food_sold && target.class == FARM_CLASS && *g.held_kind == FARM_FOOD_KIND {
        g.sold += *g.held;
        *g.held = 0.0;
        return Next::Stay;
    }
    let empty = target.amount <= 0.0 && !REGATHERED.contains(&target.master_id);
    if over < REMAINDER || empty {
        Next::Drop
    } else {
        Next::Stay
    }
}

/// State 8's update (case 7): the `MoveTo` to the drop site walks; once it ended (its update
/// in state 1 returns 1: the list deletes it and its destructor stops the unit) the load goes
/// to the player at a drop site that takes it (`site`) within `DROP_REACH` (squared): the
/// resource of what the unit carries ([`crate::gathering::hunt::resource_kind`]), which the caller adds;
/// the unit carries nothing after (`FUN_14119d310` with −1). Returns the resource and the
/// amount; the caller lets the drop site go and walks back to the target (`set_state(4)`).
/// Not modelled: the timer's wait, a `MoveTo` that waits or failed (codes 3 to 5), a site that
/// does not take the load (`set_state` 2) or is out of reach (the wait).

// the drop site gone: set_state(8) again
let Some(site) = site else {
    return Ok(Dropped::Again);
};
if !site.takes {
    self.set_idle(g);
    return Ok(Dropped::Idle);
}
if DROP_REACH < site.gap_squared {
    self.random_wait(g);
    return Ok(Dropped::Going);
}
let kind = crate::gathering::hunt::resource_kind(*g.held_kind, attributes);
let amount = *g.held;
*g.held_kind = -1;
*g.held = 0.0;
Ok(Dropped::Load(kind, amount))

/// What the constructor reads to time a farm's stops: the gatherer's work rate (its master's
/// `+0x798` plus its powerup, slot 0x6e8), its capacity (`+0x61c`) and the player's attribute the
/// task's `attribute_type2` names (none: 1.0).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct StopRate {
    /// The work rate.
    pub work_rate: f32,
    /// The capacity.
    pub capacity: f32,
    /// The productivity.
    pub productivity: f32,
}

impl StopRate {
    /// The time per stop (`+0x70`): the capacity times the productivity over the work a second,
    /// shared out over the stops.
    #[must_use]
    pub fn time_per_stop(self, work_value: f32, stops: u8) -> f32 {
        ((self.capacity * self.productivity) / (self.work_rate * work_value)) / f32::from(stops)
    }

/// The productivity the time per stop reads (the constructor's and the update's): the player's
/// attribute the task's `attribute_type2` names, as it is, or 1.0 for none (`DAT_14330eb8c`).
#[must_use]
pub fn productivity_of(attribute_type2: i16, attributes: &[f32]) -> f32 {
    if attribute_type2 == -1 {
        return DEFAULT_PRODUCTIVITY;
    }
    usize::try_from(attribute_type2)
        .ok()
        .and_then(|i| attributes.get(i))
        .copied()
        .unwrap_or(0.0)
}

impl GatherAction {
    /// The factory's constructor with a target (`FUN_140a88310`; the target's add, slot 0x178, is
    /// the caller's): the target's place is the point and its class the target type; a farm (class
    /// 49) or masters 357 and 1188 keep their place as the farm's. One stop, `mGatherX` and
    /// `mGatherY` at −1. A farm of master 50 or 1187 with the game's farm setting has four stops,
    /// each [`StopRate::time_per_stop`] long.
    ///
    /// # Errors
    ///
    /// None yet.
    pub fn new(
        task: HuntTask,
        target: &Resource,
        farm_stops: bool,
        rate: StopRate,
    ) -> Result<Self, GenieError> {
        let farm = if target.class == FARM_CLASS || SPECIAL_TARGETS.contains(&target.master) {
            [target.position[0], target.position[1]]
        } else {
            [0.0; 2]
        };
        let (stops, time_per_stop) =
            if farm_stops && target.class == FARM_CLASS && STOP_FARMS.contains(&target.master) {
                (FARM_STOPS, rate.time_per_stop(task.work_value, FARM_STOPS))
            } else {
                (1, 0.0)
            };

/// Case 5, the face: a farm not built yet is searched past (`set_state(3)`), a pasture short
/// of its animals is not modelled, a farm another farmer works waits for another (0xf3; the
/// search's notify is the caller's). Else the unit turns to its target (`FUN_141162db0`;
/// turning over time it faces next update) and works (`set_state(7)`, its time at the stop
/// 0) on a target holding something or one regathered; an empty one is not modelled.
fn update_face(
    &mut self,
    mut walk: Walk<'_>,
    target: &Victim,
    g: &mut Gatherer<'_>,
) -> Result<Next, GenieError> {
    if target.class == FARM_CLASS {
        if target.state < 2 {
            return self.begin_search(walk.mover.as_deref_mut(), g);
        }
        if (target.master_id - 0x765) & !4 == 0 {
            return Err(GenieError::unsupported(
                "a gather facing a pasture (its animals, slot 0x780)",
            ));
        }
        if 1 < target.workers {
            return self.begin_farm_wait(walk.mover.as_deref_mut(), g);
        }
    }
    let at = walk
        .world
        .get(walk.me.id)
        .map_or(walk.me.position, |p| p.position);
    let mover = walk
        .mover
        .as_deref_mut()
        .ok_or(GenieError::unsupported("a gatherer without movement state"))?;
    if !crate::combat::attack::face_target(mover, at, target.position, g.world_time)? {
        return Ok(Next::Stay);
    }
    if 0.0 < target.amount || REGATHERED.contains(&target.master_id) {
        self.set_work(walk.me.position, g);
        self.time_at_stop = 0.0;
        return Ok(Next::Stay);
    }
    Err(GenieError::unsupported(
        "a gather's target empty when faced (set_state 3)",
    ))
}

/// Case 6, the work: on a farm's stops (the game's `+0xc14` being 0) the time at the stop
/// runs; past the time per stop with a stop left the farmer walks to the next (its count
/// stays when the food is sold at once, attribute 96). Else it gathers
/// ([`GatherAction::gather`]).
fn update_work(
    &mut self,
    mut walk: Walk<'_>,
    target: &mut Victim,
    g: &mut Gatherer<'_>,
    dt: f32,
) -> Result<Next, GenieError> {
    if 1 < self.stops {
        self.time_at_stop += dt;
        if self.time_per_stop <= self.time_at_stop
            && u32::from(self.current_stop) + 1 < u32::from(self.stops)
        {
            if g.food_sold <= 0.0 {
                self.current_stop += 1;
            }
            let mover = walk
                .mover
                .as_deref_mut()
                .ok_or(GenieError::unsupported("a gatherer without movement state"))?;
            self.set_walk(target.position, target.radius, 0.0, mover, g.action_rng)?;
            return Ok(Next::Stay);
        }
    }
    Ok(self.gather(target, g, dt))

/// `RGE_Action_Object::update` (`0x14106ac90`) on a unit in state 2 without an action or a
/// production: the master's default task starts (slot 0x7f0). A default task that the slice
/// does not hold is an error.
pub(crate) fn start_default_task(
    &mut self,
    c: &mut Context<'_>,
) -> Result<DefaultTaskStarted, GenieError> {
    // RGE_Action_Object::update with no action in state 2 starts the master's default task
    // (slot 0x7f0): a bird's Fly, whose first update comes in the next tick
    let mut flies_from_now = false;
    if self.life.state == 2
        && self.top_action_kind().is_none()
        && self.production.is_none()
        && let Some(task) = self.default_fly
    {
        self.start_fly(c, task)?;
        flies_from_now = true;
    }
    let mut makes_from_now = false;
    if self.life.state == 2
        && self.top_action_kind().is_none()
        && self.production.is_none()
        && std::mem::take(&mut self.default_make)
    {
        let task = c
            .masters
            .and_then(|m| m.get(self.life.master_id))
            .and_then(Master::default_task)
            .copied()
            .ok_or(GenieError::unsupported(
                "a Make whose master the slice does not have",
            ))?;
        self.make = Some(crate::gathering::make::MakeAction::start(
            task,
            c.attributes,
            &mut crate::gathering::make::Held {
                attribute_type: &mut self.life.attribute_type,
                amount: &mut self.life.amount,
            },
        ));
        makes_from_now = true;

let started = self.start_default_task(c)?;
// The default action exists from tick 1 on, but its first update is in tick 2: fitted to
// 16 checkpoints of idle players with livestock (workspace FD-008).
let me = Me {
    id: self.id,
    position: self.position,
    group: self.group.id,
    action_state: self.top_action().map_or(0, |a| a.state),
};
// RGE_Action_Object::update runs the actions of an object not inside another (`+0x2f0`
// none as it reaches them), else the inside update, never both
let inside_at_start = self.life.inside.is_some();
let captured = self.artifact_part(c, others, me, inside_at_start, started.artifact)?;
self.build_part(c, others, me)?;
if self.repair.is_some() {
    self.repair_part(c, others, me)?;
}
self.garrison_part(c, others, me, inside_at_start, started.any())?;
// the wait for a foundation (FUN_140ae8b70) on its build points, none when the world
// does not hold it; its 1 removes it (FUN_140a98e20: the base teardown lets no target go,
// and no action follows it, the wait having replaced the list)
if let Some(w) = self.wait_solidify
    && w.update(wait_progress(w.target, others, c.foreign))
{
    self.wait_solidify = None;
}
if self.missile.as_ref().is_some_and(|m| m.action.is_some()) {
    self.fly(c, others)?;
}
self.move_to_part(c, me)?;
self.explore_part(c, me)?;
self.fly_part(c, me, started.fly)?;
self.make_part(c, started.make)?;
if self.gather.is_some() {
    self.gather_update(c, others, me)?;

/// other gatherer, with the automatic fish trap queue (`+0x1425`) or fish traps queued
/// (`+0x1420`), makes a fish trap when it is a fishing ship (class 21); else none. (For the
/// farm the game looks the spot's terrain up, `FUN_140f690e0`, `FUN_1413fbec0`,
/// `FUN_1413fc220`, `FUN_1413fc100`, and drops the answers: the master stays.) The master's
/// placement test (slot 0x50 with the explored test on, `p6` 1, whatever the player; for a
/// farm its scan passes over the gather's target and that building's annexes, `p12`,
/// [`World::placement_code_beside`]) must pass. With the automatic queue the player pays one
/// when it can without the population (`FUN_141618db0`, `FUN_14162fb60` with 1: [`cost_test`],
/// [`pay`]), else it takes one from the queue, which must hold one (else the interface's
/// event 0x7e); without the automatic queue it takes one from the queue. The master's slot
/// 0x108 makes the foundation there ([`World::make_building`], its unit AI by
/// [`crate::unit_ai::factory_type`]), the queue loses the one it gave (`FUN_14163c5b0`,
/// `FUN_14163c590`: only while above 0); the target's workers (slot 0x790, a building's
/// `+0xcb8`, which only a pasture fills: a farm's is empty, and a pasture's gather is not
/// modelled) would build it too; then the gatherer's ignore list empties (`FUN_141197da0`)
/// and its slot 0x128 sends it to build the foundation at the spot ([`World::build_task`],
/// [`World::build_directly`]). True when the foundation was made.
pub(crate) fn reseed(&mut self, p: usize, idx: usize) -> Result<bool, GenieError> {
    let unit = &self.players[p].objects[idx];
    let Some(gather) = unit.gather else {
        return Ok(false);
    };
    let farm = gather.farm;
    if farm[0] == NO_FARM {
        return Ok(false);
    }
    let class = self.master_of(p, unit.life.master_id)?.class;
    let owner = &self.players[p];
